head.b:skin:
  :root {
    --bs-primary: #198754;
  }

  /* Divisão diagonal elegante entre o verde da marca e branco, fixa atrás do conteúdo que rola */
  body {
    background: linear-gradient(135deg, #198754 0%, #198754 38%, #ffffff 38%, #ffffff 100%);
    background-attachment: fixed;
  }

  #read-progress {
    position: fixed;
    top: 0;
    left: 0;
    height: 3px;
    background: #ffffff;
    z-index: 1050;
    width: 0%;
  }


/* ==========================================================================
   CSS DE SANITIZAÇÃO DO BLOGGER (BLOQUEIO DE LIXO ESTRUTURAL)
   ========================================================================== */

/* 1. Ocultar Elementos Nativos, Ícones de Admin e Scripts Injetados */
#navbar-iframe,
.navbar-iframe,
.quickedit,
.widget-item-control,
.item-control,
.blog-admin,
.post-feeds,
.feed-links,
#attributions,
.attribution,
.status-msg-wrap,
.status-msg-border,
.status-msg-body,
.status-msg-bg,
.home-link,
.blog-pager-newer-link,
.blog-pager-older-link,
.post-footer-line-1,
.post-footer-line-2,
.post-footer-line-3 {
  display: none !important;
  visibility: hidden !important;
  height: 0 !important;
  width: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  opacity: 0 !important;
  pointer-events: none !important;
}

/* 2. Neutralizar Wrappers e Margens Fantasmas das Tags <b:section> e <b:widget> */
.section,
.widget,
.widget-content,
.Blog,
.blog-posts,
.post-outer,
.post {
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  float: none !important;
}

/* 3. Reset de Espaçamento das Mídias e Títulos Padrão */
.post-body img,
.widget img {
  max-width: 100%;
  height: auto;
  border: 0 !important;
  outline: none !important;
  box-shadow: none;
}

/* 4. Trava de Deslocamento do Topo (Empurrão do Navbar antigo) */
body {
  top: 0 !important;
  position: relative;
}

/* ==========================================================================
   OTIMIZAÇÕES MOBILE-FIRST PARA BOOTSTRAP 5
   ========================================================================== */

/* 1. Trava de Overflow Lateral e Otimização Touch */
html, body {
  overflow-x: hidden;
  width: 100%;
  -webkit-tap-highlight-color: transparent;
  -webkit-text-size-adjust: 100%;
  touch-action: manipulation;
}

/* 2. Área Mínima de Toque Acessível (44px x 44px - Padrão Apple/Google) */
.btn,
.nav-link,
.form-control,
.form-select,
.accordion-button,
.dropdown-item {
  min-height: 44px;
  display: inline-flex;
  align-items: center;
}

/* 3. Ajustes de Layout e Tipografia para Telas Pequenas (< 576px) */
@media (max-width: 575.98px) {
  /* Contêineres com padding lateral seguro */
  .container,
  .container-fluid {
    padding-left: 1rem;
    padding-right: 1rem;
  }

  /* Escala de Títulos Otimizada para Mobile */
  h1, .h1 { font-size: calc(1.4rem + 1.2vw) !important; line-height: 1.25; }
  h2, .h2 { font-size: calc(1.25rem + 0.8vw) !important; line-height: 1.3; }
  h3, .h3 { font-size: calc(1.15rem + 0.4vw) !important; }

  /* Redução de Padding de Seções e Cards para Economizar Espaço */
  .card-body {
    padding: 1rem !important;
  }

  section,
  .py-5 {
    padding-top: 2rem !important;
    padding-bottom: 2rem !important;
  }

  /* Menu Drawer / Offcanvas Otimizado para Thumb-Zone */
  .offcanvas-end,
  .offcanvas-start {
    width: 85% !important;
    max-width: 320px;
  }

  /* Botões de Ação Full-Width no Mobile */
  .btn-mobile-full {
    width: 100% !important;
    justify-content: center;
  }
}

/* 4. Rolagem Fluida com Aceleração de Hardware */
.offcanvas-body,
.table-responsive,
.nav-scroller {
  -webkit-overflow-scrolling: touch;
  overscroll-behavior-y: contain;
}

@media (prefers-reduced-motion: no-preference) {
  html {
    scroll-behavior: smooth;
  }
}

/* 5. Tabelas Responsivas sem Quebrar a Tela */
.table-responsive {
  border-radius: 0.375rem;
  white-space: nowrap;
}


/* ==========================================================================
   CSS DO GRID DE POSTAGENS (RESPONSIVO E OTIMIZADO)
   ========================================================================== */

/* 1. Card Base e Aspect Ratio Contido */
.post-card {
  transition: transform 0.25s ease, box-shadow 0.25s ease;
  border: none;
  overflow: hidden;
  height: 100%;
  display: flex;
  flex-direction: column;
  background-color: #ffffff;
}

.post-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 0.75rem 1.5rem rgba(0, 0, 0, 0.12) !important;
}

/* 2. Container de Imagem Destaque (Evita CLS e Quebra de Layout) */
.post-thumb-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  background-color: #e9ecef;
}

.post-thumb-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.35s ease;
}

.post-card:hover .post-thumb-img {
  transform: scale(1.04);
}

/* 3. Truncamento de Texto (Line Clamp) */
.post-card-title {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1.3;
}

.post-card-excerpt {
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
  text-overflow: ellipsis;
  color: #6c757d;
  font-size: 0.875rem;
  line-height: 1.5;
}

/* 4. Rodapé do Card e Badges de Categoria */
.post-card-meta {
  margin-top: auto;
  font-size: 0.75rem;
  color: #8c98a4;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.post-category-badge {
  position: absolute;
  top: 10px;
  left: 10px;
  z-index: 2;
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 0.35em 0.65em;
}

/* 5. Ajustes para Mobile (< 576px) */
@media (max-width: 575.98px) {
  .post-thumb-wrapper {
    aspect-ratio: 16 / 9;
  }

  .post-card-title {
    font-size: 1rem;
  }
}
/* Tipografia e Leitura Interna do Post */
.post-body {
  font-size: 1.05rem;
  line-height: 1.8;
  color: #2b2b2b;
}

.post-body h2 {
  font-size: 1.6rem;
  font-weight: 700;
  margin-top: 2rem;
  margin-bottom: 1rem;
}

.post-body h3 {
  font-size: 1.3rem;
  font-weight: 600;
  margin-top: 1.5rem;
  margin-bottom: 0.75rem;
}

.post-body p {
  margin-bottom: 1.25rem;
}

/* Blocos de Citação (Blockquote) */
.post-body blockquote {
  border-left: 4px solid var(--bs-primary, #198754);
  padding: 0.8rem 1.25rem;
  margin: 1.5rem 0;
  background-color: #f8f9fa;
  border-radius: 0 0.375rem 0.375rem 0;
  font-style: italic;
  color: #495057;
}

/* Blocos de Código (Pre e Code) */
.post-body pre {
  background-color: #212529;
  color: #f8f9fa;
  padding: 1rem;
  border-radius: 0.5rem;
  overflow-x: auto;
  font-size: 0.875rem;
  margin: 1.5rem 0;
}

.post-body :not(pre) > code {
  background-color: #e9ecef;
  color: #d63384;
  padding: 0.2rem 0.4rem;
  border-radius: 0.25rem;
  font-size: 0.875em;
}

/* Imagens Internas e Tabelas */
.post-body img {
  max-width: 100%;
  height: auto;
  border-radius: 0.5rem;
  margin: 1rem 0;
}

.post-body table {
  width: 100%;
  margin-bottom: 1rem;
  border-collapse: collapse;
}

.post-body table th,
.post-body table td {
  padding: 0.75rem;
  border: 1px solid #dee2e6;
}
/* Paginação Responsiva */
.blog-pager {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 2.5rem;
  padding-top: 1.5rem;
  border-top: 1px solid #dee2e6;
}

.blog-pager-newer-link,
.blog-pager-older-link {
  display: inline-flex;
  align-items: center;
  padding: 0.5rem 1.25rem;
  font-weight: 600;
  color: #212529;
  background-color: #ffffff;
  border: 1px solid #dee2e6;
  border-radius: 0.375rem;
  text-decoration: none;
  transition: background-color 0.2s ease, border-color 0.2s ease;
}

.blog-pager-newer-link:hover,
.blog-pager-older-link:hover {
  background-color: #f8f9fa;
  border-color: #adb5bd;
  color: #000000;
}

 /* Estilização da Sidebar */
.sidebar .widget {
  margin-bottom: 2rem;
  background: #ffffff;
  padding: 1.25rem;
  border-radius: 0.5rem;
}

.sidebar .widget-title {
  font-size: 1.1rem;
  font-weight: 700;
  padding-bottom: 0.5rem;
  margin-bottom: 1rem;
  border-bottom: 2px solid var(--bs-primary, #198754);
}

/* Nuvem de Tags / Categorias (Widget de Marcadores) */
.widget.Label ul {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.widget.Label .label-size {
  display: inline-block;
  font-size: 0.75rem !important;
  padding: 0.35em 0.75em;
  background-color: #f8f9fa;
  border: 1px solid #dee2e6;
  border-radius: 50rem;
  color: #495057;
  text-decoration: none;
  transition: all 0.2s ease;
}

.widget.Label .label-size:hover {
  background-color: var(--bs-primary, #198754);
  color: #ffffff;
  border-color: var(--bs-primary, #198754);
}
/* Card de Biografia do Autor */
.author-box {
  background-color: #f8f9fa;
  border-radius: 0.5rem;
  padding: 1.25rem;
  margin-top: 2rem;
  display: flex;
  align-items: center;
  gap: 1rem;
}

.author-avatar {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  object-fit: cover;
}

/* Ajustes no Container do Iframe de Comentários */
#comments {
  margin-top: 3rem;
  padding-top: 1.5rem;
  border-top: 1px solid #dee2e6;
}

#comment-editor {
  width: 100% !important;
  min-height: 220px;
  border: none;
}

/* Card de Biografia do Autor */
.author-box {
  background-color: #f8f9fa;
  border-radius: 0.5rem;
  padding: 1.25rem;
  margin-top: 2rem;
  display: flex;
  align-items: center;
  gap: 1rem;
}

.author-avatar {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  object-fit: cover;
}

/* Ajustes no Container do Iframe de Comentários */
#comments {
  margin-top: 3rem;
  padding-top: 1.5rem;
  border-top: 1px solid #dee2e6;
}

#comment-editor {
  width: 100% !important;
  min-height: 220px;
  border: none;
}

/* Acessibilidade de Foco via Teclado */
:focus-visible {
  outline: 3px solid var(--bs-primary, #198754) !important;
  outline-offset: 2px;
}

/* CSS para Impressão de Artigos */
@media print {
  nav, footer, .sidebar, #faq, .blog-pager, .btn {
    display: none !important;
  }

  body {
    background: #ffffff !important;
    color: #000000 !important;
  }

  .post-body {
    font-size: 12pt;
    line-height: 1.5;
  }
}
 /* ==========================================================================
   CSS DO RODAPÉ (FOOTER RESPONSIVO E WIDGETS)
   ========================================================================== */

/* 1. Estrutura Base do Rodapé */
.site-footer {
  background-color: #0f172a; /* Tom escuro para alto contraste */
  color: #94a3b8;
  padding-top: 4rem;
  padding-bottom: 2rem;
  border-top: 1px solid #1e293b;
  font-size: 0.9rem;
}

/* 2. Títulos e Blocos dos Widgets no Footer */
.site-footer .widget-title,
.site-footer h5,
.site-footer h6 {
  color: #f8fafc;
  font-family: 'Poppins', sans-serif;
  font-weight: 600;
  font-size: 1.05rem;
  margin-bottom: 1.25rem;
  position: relative;
}

.site-footer .widget {
  margin-bottom: 2rem;
  background: transparent !important;
  border: none !important;
  padding: 0 !important;
}

/* 3. Listas de Links e Navegação do Rodapé */
.footer-links {
  list-style: none;
  padding: 0;
  margin: 0;
}

.footer-links li {
  margin-bottom: 0.65rem;
}

.footer-links a {
  color: #94a3b8;
  text-decoration: none;
  transition: color 0.2s ease, transform 0.2s ease;
  display: inline-block;
}

.footer-links a:hover {
  color: #38bdf8; /* Azul destaque */
  transform: translateX(4px);
}

/* 4. Ícones Sociais */
.social-links {
  display: flex;
  gap: 0.75rem;
}

.social-btn {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background-color: #1e293b;
  color: #f8fafc;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  text-decoration: none;
  transition: background-color 0.2s ease, transform 0.2s ease;
}

.social-btn:hover {
  background-color: var(--bs-primary, #2563eb);
  color: #ffffff;
  transform: translateY(-3px);
}

/* 5. Barra Inferior de Copyright e Termos */
.footer-bottom {
  margin-top: 3rem;
  padding-top: 1.5rem;
  border-top: 1px solid #1e293b;
  font-size: 0.825rem;
  color: #64748b;
}

.footer-bottom a {
  color: #94a3b8;
  text-decoration: none;
}

.footer-bottom a:hover {
  color: #ffffff;
}

/* 6. Ajustes Responsivos Mobile (< 768px) */
@media (max-width: 767.98px) {
  .site-footer {
    padding-top: 2.5rem;
    padding-bottom: 1.5rem;
    text-align: left;
  }

  .footer-bottom {
    margin-top: 2rem;
    flex-direction: column;
    gap: 1rem;
    text-align: center;
  }
}


  /* ==========================================================================
     MODO ESCURO — ativa o toggle #theme-toggle (JS já existente no template)
     ========================================================================== */
  [data-bs-theme="dark"] body {
    background-color: #0f172a;
    color: #e2e8f0;
  }

  [data-bs-theme="dark"] .navbar {
    background-color: #0f172a !important;
    border-color: #1e293b !important;
  }

  [data-bs-theme="dark"] .navbar-brand,
  [data-bs-theme="dark"] .nav-link {
    color: #e2e8f0 !important;
  }

  [data-bs-theme="dark"] .post-card,
  [data-bs-theme="dark"] .sidebar .widget,
  [data-bs-theme="dark"] .accordion-item,
  [data-bs-theme="dark"] .accordion-body {
    background-color: #1e293b !important;
    color: #e2e8f0;
  }

  [data-bs-theme="dark"] .post-body {
    color: #cbd5e1;
  }

  [data-bs-theme="dark"] .post-body a {
    color: #38bdf8;
    text-decoration-color: rgba(56, 189, 248, 0.3);
  }

  [data-bs-theme="dark"] .post-body a:hover {
    color: #7dd3fc;
    background-color: rgba(56, 189, 248, 0.12);
  }

  [data-bs-theme="dark"] .post-body blockquote {
    background-color: #0f172a;
    color: #cbd5e1;
    border-left-color: #38bdf8;
  }

  [data-bs-theme="dark"] .post-body th {
    background-color: #0f172a;
    color: #f8fafc;
  }

  [data-bs-theme="dark"] .post-body th,
  [data-bs-theme="dark"] .post-body td {
    border-color: #334155;
  }

  [data-bs-theme="dark"] .footer-links a {
    color: #94a3b8;
  }

  [data-bs-theme="dark"] .footer-links a:hover {
    color: #38bdf8;
  }

  [data-bs-theme="dark"] .theme-toggle-btn {
    border-color: #334155;
    color: #fbbf24;
  }

  /* Botão alternador de tema (Sol/Lua) */
  .theme-toggle-btn {
    width: 38px;
    height: 38px;
    padding: 0;
    border-radius: 50%;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: 1px solid #cbd5e1;
    background-color: transparent;
    color: #334155;
    transition: all 0.2s ease;
  }

  .theme-toggle-btn:hover {
    background-color: rgba(0, 0, 0, 0.05);
  }

  [data-bs-theme="dark"] .theme-toggle-btn:hover {
    background-color: rgba(255, 255, 255, 0.08);
  }

  .theme-toggle-btn .icon-sun { display: none; }
  .theme-toggle-btn .icon-moon { display: inline-block; }
  [data-bs-theme="dark"] .theme-toggle-btn .icon-sun { display: inline-block; }
  [data-bs-theme="dark"] .theme-toggle-btn .icon-moon { display: none; }

  .theme-toggle-btn svg {
    width: 20px;
    height: 20px;
    stroke: currentColor;
    stroke-width: 2;
    fill: none;
  }

  /* Botão voltar ao topo (JS já existente no template) */
  #back-to-top {
    opacity: 0;
    visibility: hidden;
    transition: opacity 0.3s ease, visibility 0.3s ease;
  }
  #back-to-top.show {
    opacity: 1;
    visibility: visible;
  }

  /* Caixa de sumário (TOC) */
  .toc-box {
    font-size: 0.9rem;
  }

  /* Busca instantânea */
  #search-results {
    max-height: 300px;
    overflow-y: auto;
  }

  /* Seleção de texto e barra de rolagem */
  ::selection {
    background-color: rgba(25, 135, 84, 0.2);
    color: var(--bs-primary, #198754);
  }
  [data-bs-theme="dark"] ::selection {
    background-color: rgba(56, 189, 248, 0.3);
    color: #38bdf8;
  }
  ::-webkit-scrollbar { width: 8px; height: 8px; }
  ::-webkit-scrollbar-track { background: #f1f5f9; }
  ::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 4px; }
  ::-webkit-scrollbar-thumb:hover { background: #94a3b8; }
  [data-bs-theme="dark"] ::-webkit-scrollbar-track { background: #0f172a; }
  [data-bs-theme="dark"] ::-webkit-scrollbar-thumb { background: #334155; }
  [data-bs-theme="dark"] ::-webkit-scrollbar-thumb:hover { background: #475569; }

body.script:
//
  document.addEventListener('DOMContentLoaded', () => {
  // -----------------------------------------------------------------
  // 1. Barra de Progresso de Leitura (Single Posts)
  // -----------------------------------------------------------------
  const progressBar = document.getElementById('read-progress');
  if (progressBar) {
    window.addEventListener('scroll', () => {
      const winScroll = document.documentElement.scrollTop || document.body.scrollTop;
      const height = document.documentElement.scrollHeight - document.documentElement.clientHeight;
      const scrolled = (winScroll / height) * 100;
      progressBar.style.width = `${scrolled}%`;
    }, { passive: true });
  }

  // -----------------------------------------------------------------
  // 2. Gerador Automático de Sumário / TOC (Table of Contents)
  // -----------------------------------------------------------------
  const postBody = document.querySelector('.post-body');
  const tocContainer = document.getElementById('auto-toc');

  if (postBody && tocContainer) {
    const headings = postBody.querySelectorAll('h2, h3');
    if (headings.length >= 2) {
      const tocList = document.createElement('ul');
      tocList.className = 'list-unstyled mb-0 small';

      headings.forEach((heading, index) => {
        const id = heading.id || `section-${index + 1}`;
        heading.id = id;

        const li = document.createElement('li');
        li.className = heading.tagName === 'H3' ? 'ms-3 my-1' : 'my-1';

        const a = document.createElement('a');
        a.href = `#${id}`;
        a.textContent = heading.textContent;
        a.className = 'text-decoration-none text-secondary hover-primary';

        li.appendChild(a);
        tocList.appendChild(li);
      });

      tocContainer.appendChild(tocList);
    } else {
      // Se não houver títulos suficientes, oculta a caixa de sumário
      const tocBox = tocContainer.closest('.toc-box');
      if (tocBox) tocBox.style.display = 'none';
    }
  }

  // -----------------------------------------------------------------
  // 3. Botão "Copiar Código" em Blocos <pre>
  // -----------------------------------------------------------------
  const codeBlocks = document.querySelectorAll('.post-body pre');
  codeBlocks.forEach((block) => {
    // Wrapper para posicionar o botão
    block.style.position = 'relative';

    const copyBtn = document.createElement('button');
    copyBtn.className = 'btn btn-sm btn-outline-light position-absolute top-0 end-0 m-2';
    copyBtn.style.zIndex = '5';
    copyBtn.style.fontSize = '0.75rem';
    copyBtn.innerHTML = 'Copiar';

    copyBtn.addEventListener('click', async () => {
      const code = block.querySelector('code') ? block.querySelector('code').innerText : block.innerText;
      try {
        await navigator.clipboard.writeText(code);
        copyBtn.innerHTML = 'Copiado!';
        copyBtn.classList.replace('btn-outline-light', 'btn-success');
        setTimeout(() => {
          copyBtn.innerHTML = 'Copiar';
          copyBtn.classList.replace('btn-success', 'btn-outline-light');
        }, 2000);
      } catch (err) {
        console.error('Falha ao copiar:', err);
      }
    });

    block.appendChild(copyBtn);
  });

  // -----------------------------------------------------------------
  // 4. Botão Voltar ao Topo (Back to Top)
  // -----------------------------------------------------------------
  const backToTopBtn = document.getElementById('back-to-top');
  if (backToTopBtn) {
    window.addEventListener('scroll', () => {
      if (window.scrollY > 300) {
        backToTopBtn.classList.add('show');
      } else {
        backToTopBtn.classList.remove('show');
      }
    }, { passive: true });

    backToTopBtn.addEventListener('click', (e) => {
      e.preventDefault();
      window.scrollTo({ top: 0, behavior: 'smooth' });
    });
  }

  // -----------------------------------------------------------------
  // 5. Compartilhamento Nativo (Web Share API + Fallback Clipboard)
  // -----------------------------------------------------------------
  const shareBtn = document.getElementById('btn-web-share');
  if (shareBtn) {
    shareBtn.addEventListener('click', async (e) => {
      e.preventDefault();
      const shareData = {
        title: document.title,
        url: window.location.href
      };

      if (navigator.share) {
        try {
          await navigator.share(shareData);
        } catch (err) {
          /* Compartilhamento cancelado pelo usuário */
        }
      } else {
        // Fallback: Copia URL para a área de transferência
        navigator.clipboard.writeText(window.location.href);
        alert('Link do artigo copiado para a área de transferência!');
      }
    });
  }

  // -----------------------------------------------------------------
  // 6. Dark / Light Mode Toggle (Suporte Nativo Bootstrap 5.3+)
  // -----------------------------------------------------------------
  const themeToggleBtn = document.getElementById('theme-toggle');
  const storedTheme = localStorage.getItem('theme') || (window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');

  const setTheme = (theme) => {
    document.documentElement.setAttribute('data-bs-theme', theme);
    localStorage.setItem('theme', theme);
  };

  // Aplica o tema salvo imediatamente
  setTheme(storedTheme);

  if (themeToggleBtn) {
    themeToggleBtn.addEventListener('click', () => {
      const currentTheme = document.documentElement.getAttribute('data-bs-theme');
      const newTheme = currentTheme === 'dark' ? 'light' : 'dark';
      setTheme(newTheme);
    });
  }

  // -----------------------------------------------------------------
  // 7. Busca Instantânea em Tempo Real (Blogger JSON Feed)
  // -----------------------------------------------------------------
  const searchInput = document.getElementById('search-input');
  const searchResults = document.getElementById('search-results');

  if (searchInput && searchResults) {
    let debounceTimer;

    searchInput.addEventListener('input', (e) => {
      clearTimeout(debounceTimer);
      const query = e.target.value.trim();

      if (query.length < 3) {
        searchResults.innerHTML = '';
        searchResults.classList.add('d-none');
        return;
      }

      debounceTimer = setTimeout(async () => {
        try {
          const response = await fetch(`/feeds/posts/summary?alt=json&q=${encodeURIComponent(query)}&max-results=5`);
          const data = await response.json();
          const entries = data.feed.entry || [];

          if (entries.length === 0) {
            searchResults.innerHTML = '<div class="p-3 text-muted small text-center">Nenhum resultado encontrado.</div>';
          } else {
            searchResults.innerHTML = entries.map(entry => {
              const title = entry.title.$t;
              const link = entry.link.find(l => l.rel === 'alternate').href;
              return `
                <a href="${link}" class="list-group-item list-group-item-action p-2">
                  <span class="small fw-semibold text-truncate">${title}</span>
                </a>
              `;
            }).join('');
          }
          searchResults.classList.remove('d-none');
        } catch (err) {
          console.error('Erro na busca instantânea:', err);
        }
      }, 300);
    });

    document.addEventListener('click', (e) => {
      if (!searchInput.contains(e.target) && !searchResults.contains(e.target)) {
        searchResults.classList.add('d-none');
      }
    });
  }

  // -----------------------------------------------------------------
  // 8. Prefetch Inteligente ao Passar o Mouse em Links Internos
  // -----------------------------------------------------------------
  document.querySelectorAll('a[href^="/"]').forEach(link => {
    link.addEventListener('mouseenter', () => {
      const href = link.getAttribute('href');
      if (href && !document.querySelector(`link[rel="prefetch"][href="${href}"]`)) {
        const prefetchLink = document.createElement('link');
        prefetchLink.rel = 'prefetch';
        prefetchLink.href = href;
        document.head.appendChild(prefetchLink);
      }
    }, { once: true });
  });

  // -----------------------------------------------------------------
  // 9. Otimizador Dinâmico de Imagens do Blogger (WebP + Resize)
  // -----------------------------------------------------------------
  document.querySelectorAll('.post-body img').forEach(img => {
    let src = img.getAttribute('src');
    if (src && src.includes('blogspot.com')) {
      src = src.replace(/\/s\d+(-c)?\//, '/w800-rw/').replace(/\/w\d+-h\d+(-c)?\//, '/w800-rw/');
      img.setAttribute('src', src);
    }
    img.setAttribute('loading', 'lazy');
    img.setAttribute('decoding', 'async');
  });
});

